<div class="col-12 col-md-5"><label for="search{{ isset($filterUrl) ? md5($filterUrl) : '' }}" class="form-label">Party name or mobile</label><input id="search{{ isset($filterUrl) ? md5($filterUrl) : '' }}" type="search" name="search" class="form-control" value="{{ request('search') }}" placeholder="Search party..."></div>
<div class="col-12 col-md-3"><label class="form-label">Approval</label><select name="approval" class="form-select"><option value="">All</option><option value="pending" @selected(request('approval') === 'pending')>Pending</option><option value="approved" @selected(request('approval') === 'approved')>Approved</option></select></div>
<div class="col-6 col-md-auto"><button class="btn btn-primary w-100" type="submit">Apply</button></div>
<div class="col-6 col-md-auto"><a href="{{ $filterUrl }}" class="btn btn-outline-secondary w-100 va-clear-filters">Clear</a></div>
